            throw new Error("Login couldn't finish: no authorization code.");
        return code;
    }
    return new Promise((resolve, reject) => {
        const frame = document.createElement("iframe");
        frame.style.display = "none";
        const done = () => {
            window.removeEventListener("message", onMessage);
            clearTimeout(timer);
            frame.remove();
        };
        const onMessage = (e) => {
            const data = e.data;
            if (!data || data.state !== state)
                return; // a message not meant for us
            done();
            if (data.error)
                reject(new Error(`Login was refused: ${data.error}`));
            else if (data.code)
                resolve(data.code);
            else
                reject(new Error("Login couldn't finish: no authorization code."));
        };
        const timer = setTimeout(() => {
            done();
            reject(new Error("Login timed out. Is this page's origin on the OAuth app's allowed domains?"));
        }, 120_000);
        window.addEventListener("message", onMessage);
        frame.src = url;
        document.body.appendChild(frame);
    });
}
